const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location (Villarrica, Chile)
  const villarrica = ee.Geometry.Point([-72.23, -39.28]);

  // 2. Define time periods
  const date2021Start = '2021-01-01';
  const date2021End = '2021-12-31';
  const date2016Start = '2016-01-01';
  const date2016End = '2016-12-31';

  // 3. Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // 4. Filter for 2021
  const precip2021 = chirps.filterDate(date2021Start, date2021End)
                          .filterBounds(villarrica);

  const count2021 = precip2021.size().getInfo();
  console.log(`2021 Images: ${count2021}`);

  if (count2021 === 0) {
    console.log('No data for 2021.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Filter for 2016
  const precip2016 = chirps.filterDate(date2016Start, date2016End)
                          .filterBounds(villarrica);

  const count2016 = precip2016.size().getInfo();
  console.log(`2016 Images: ${count2016}`);

  if (count2016 === 0) {
    console.log('No data for 2016.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Calculate total rainfall for each year
  const total2021 = precip2021.select('precipitation').sum();
  const total2016 = precip2016.select('precipitation').sum();

  // 7. Reduce to get values at Villarrica
  const rainfall2021 = total2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: villarrica,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const rainfall2016 = total2016.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: villarrica,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 8. Check for valid results
  if (rainfall2021 === null || rainfall2016 === null) {
    console.log('Calculation failed - null result');
    console.log('<answer>C3</answer>');
    return;
  }

  if (isNaN(rainfall2021) || isNaN(rainfall2016)) {
    console.log('Calculation failed - NaN result');
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Print results
  console.log(`2021 Total Rainfall: ${rainfall2021.toFixed(2)} mm`);
  console.log(`2016 Total Rainfall: ${rainfall2016.toFixed(2)} mm`);
  console.log(`Difference: ${(rainfall2021 - rainfall2016).toFixed(2)} mm`);

  // 10. Determine answer
  if (rainfall2021 > rainfall2016) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
